bool dfs(int curr, vector<int> adj[], vector<int> &rec, vector<int> &vis)
{
    if (rec[curr])
        return true;

    struct Frame { int node; size_t idx; };
    std::stack<Frame> st;
    st.push({curr, 0});
    rec[curr] = 1;

    while (!st.empty()) {
        Frame &fr = st.top();
        int node = fr.node;

        if (fr.idx < adj[node].size()) {
            int nb = adj[node][fr.idx++];
            if (rec[nb])
                return true;
            if (!vis[nb]) {
                rec[nb] = 1;
                st.push({nb, 0});
            }
        } else {
            vis[node] = 1;
            rec[node] = 0;
            st.pop();
        }
    }
    return false;
}

