std::string countAndSay(int n) {
    if (n <= 0) return "";
    if (n == 1) return "1";

    std::stack<std::pair<int,bool>> st;
    st.push({n, false});
    std::string value;

    while (!st.empty()) {
        auto [cur, visited] = st.top();
        st.pop();

        if (cur == 1) {
            value = "1";
            continue;
        }

        if (!visited) {
            // simulate the recursive call countAndSay(cur-1)
            st.push({cur, true});
            st.push({cur - 1, false});
        } else {
            // cur is ready, its sub-result is in 'value'
            const std::string &sub = value;
            std::string ans;
            ans.reserve(sub.size() * 2);

            char prev = sub[0];
            int cnt = 1;
            for (size_t i = 1; i <= sub.size(); ++i) {
                if (i == sub.size() || sub[i] != prev) {
                    ans += std::to_string(cnt);
                    ans.push_back(prev);
                    if (i < sub.size()) {
                        prev = sub[i];
                        cnt = 1;
                    }
                } else {
                    ++cnt;
                }
            }
            value.swap(ans);
        }
    }
    return value;
}

