void heapify(int A[], int n, int i)
{
  int large = i;
  int left = 2 * i + 1, right = 2 * i + 2;

  if (left < n && A[large] < A[left])
    large = left;
  if (right < n && A[large] < A[right])
    large = right;

  // large me largest wale ka index hai hai teeno me se
  if (large == i)
    return;
  swap(A[large], A[i]);
  heapify(A, n, large);
}

