int fast_power(int a, int b)
{
    if (b == 0) return 1;
    if (b < 0) return 0; // undefined for negative exponent in int domain

    std::stack<int> st;
    int cur = b;
    while (cur > 0) {
        st.push(cur);
        cur /= 2;
    }

    long long result = 1;
    while (!st.empty()) {
        int curB = st.top();
        st.pop();
        result = result * result;
        if (curB & 1) result *= a;
    }
    return static_cast<int>(result);
}

