char kthCharacter(long long k, vector<int>& operations) {
    // Explicit call-stack simulation
    std::stack<long long> st;
    st.push(k);

    long long increments = 0;
    int n = operations.size();

    while (!st.empty()) {
        long long curK = st.top();
        st.pop();

        if (curK == 1) {
            continue; // base case reached
        }

        long long len = 1;
        int opType = 0;
        long long newK = curK;

        for (int i = 0; i < n; ++i) {
            len <<= 1; // len *= 2
            if (len >= curK) {
                opType = operations[i];
                newK = curK - len / 2; // the recursive call argument
                break;
            }
        }

        if (opType == 1) {
            ++increments;
        }
        // push the item the recursive call would have been made on
        st.push(newK);
    }

    char res = 'a' + static_cast<char>(increments % 26);
    return res;
}

