#include <stack>

int findWinnerIdx(int n, int k) {
    if (n <= 0) return -1;
    if (n == 1) return 0;

    struct Frame {
        int n;
        int k;
        bool processed;
    };

    std::stack<Frame> st;
    st.push({n, k, false});

    int idx = 0;
    while (!st.empty()) {
        Frame f = st.top();
        st.pop();

        if (f.n == 1) {
            idx = 0;
            continue;
        }

        if (!f.processed) {
            // push parent back for post-processing after child
            st.push({f.n, f.k, true});
            // push the recursive call that would have been made
            st.push({f.n - 1, f.k, false});
        } else {
            // post-processing step: idx = (child_idx + k) % n
            idx = (idx + f.k) % f.n;
        }
    }
    return idx;
}

