double power(double x, int n)
{
    if (n == 0) return 1.00;
    if (n == 1) return x;

    std::stack<int> st;
    st.push(n);
    std::stack<int> path;

    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        path.push(cur);
        if (cur == 0 || cur == 1) break;
        st.push(cur / 2);
    }

    double ans = path.top() == 0 ? 1.0 : x;
    path.pop();

    while (!path.empty()) {
        int nn = path.top();
        path.pop();
        if (nn % 2 == 0) {
            ans = ans * ans;
        } else if (nn < 0) {
            ans = ans * ans / x;
        } else {
            ans = ans * ans * x;
        }
    }
    return ans;
}

