int pow(int b, int p) {            // O(log(p) base 2)
    if(p == 0)    return 1;
    int sq = pow(b, p/2);
    sq = sq*sq;

    if(p%2 == 1)
        sq = sq*b;

    return sq;
}

int64_t gcdExtended(const int64_t& a, const int64_t& b, int64_t& x,
                    int64_t& y) {
    if (a == 0) {
        x = 0;
        y = 1;
        return b;
    }

    int64_t x1 = 0, y1 = 0;
    const int64_t gcd = gcdExtended(b % a, a, x1, y1);

    x = y1 - (b / a) * x1;
    y = x1;
    return gcd;
}

