int spiralDiaSum(int n) {
    if (n == 1) return 1;
    std::stack<int> st;
    st.push(n);
    long long sum = 0;
    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        if (cur == 1) {
            sum += 1;
            continue;
        }
        sum += 4LL * cur * cur - 6LL * cur + 6;
        st.push(cur - 2);
    }
    return static_cast<int>(sum);
}

