bool isPalUtil(int num, int* dupNum) {
    struct Frame { int num; bool visited; };
    std::stack<Frame> st;
    st.push({num, false});
    while (!st.empty()) {
        Frame f = st.top(); st.pop();
        if (oneDigit(f.num)) {
            if (f.num != (*dupNum) % 10) return false;
        } else {
