#include <stack>

double arr_average(double arr[], int len) {
    if (len <= 0) return 0.0;
    std::stack<int> st;
    st.push(len);                 // push the starting item
    double sum = 0.0;
    while (!st.empty()) {         // loop while stack is not empty
        int cur = st.top();
        st.pop();                 // pop one item
        sum += arr[cur - 1];
        if (cur > 1) {
            st.push(cur - 1);     // push the item the recursive call would have been made on
        }
    }
    return sum / len;             // signature and result identical to the recursive version
}

