int Neumann2_4_12(int n) {
    // explicit stack replaces the implicit call stack
    if (n < 0) return 0; // guard, original would recurse infinitely
    std::stack<int> st;
    st.push(n);

    int total = 0;
    while (!st.empty()) {
        int cur = st.top();
        st.pop();

        if (cur == 0) {
            total += 1;               // base case
        } else {
            total += 4 * cur;         // work that would be done after the recursive call returns
            st.push(cur - 1);         // push the item the recursive call would have been made on
        }
    }
    return total;
}

