void dfs(vector<int>& freq, int index, string& cur, vector<string>& res){
    struct State {
        vector<int> freq;
        int index;
        string cur;
    };

    std::stack<State> st;
    st.push({freq, index, cur});

    while (!st.empty()) {
        State s = std::move(st.top());
        st.pop();

        if (s.index >= (int)s.cur.size() / 2) {
            res.push_back(std::move(s.cur));
            continue;
        }

        // push children in reverse order so the first child is processed first with LIFO
