            if (s.freq[ch]) {
                State next;
                next.freq = s.freq;
                next.index = s.index + 1;
                next.cur = s.cur;
                next.cur[s.index] = next.cur[next.cur.size() - s.index - 1] = static_cast<char>(ch);
                next.freq[ch] -= 2;
                st.push(std::move(next));
            }
        }
    }
}

