bool dfs(const vector<int>& nums, int index, vector<int>& cur){
    struct Frame {
        int index;
        size_t next_i;
        vector<int> cur;
    };
    std::stack<Frame> st;
    st.push({index, 0, cur});

    while(!st.empty()){
        Frame &fr = st.top();

        if(fr.index == static_cast<int>(nums.size())){
            bool allZero = true;
            for(int e : fr.cur){
                if(e != 0){ allZero = false; break; }
            }
            if(allZero) return true;
            st.pop();
            continue;
        }

        if(fr.next_i >= fr.cur.size()){
            st.pop();
            continue;
        }

        size_t i = fr.next_i++;
        if(fr.cur[i] >= nums[fr.index]){
            vector<int> newCur = fr.cur;
            newCur[i] -= nums[fr.index];
            st.push({fr.index + 1, 0, std::move(newCur)});
        }
    }
    return false;
}

