unsigned int fact(unsigned int n) {
    std::stack<unsigned int> st;
    st.push(n);
    unsigned int result = 1;
    while (!st.empty()) {
        unsigned int cur = st.top();
        st.pop();
        if (cur == 0) {
            continue;
        }
        result *= cur;
        st.push(cur - 1);
    }
