int minSwaps(string str, int l, int r, int cnt, int minm) {
    struct State {
        string s;
        int l;
        int r;
        int cnt;
    };
    std::stack<State> st;
    st.push({str, l, r, cnt});
    int best = minm;
    while (!st.empty()) {
        State cur = st.top();
        st.pop();
        if (cur.l >= cur.r) {
            if (sameCharAdj(cur.s)) {
                best = std::min(best, cur.cnt);
            }
            continue;
        }
        // explore the non-swap continuation once
        st.push({cur.s, cur.l + 1, cur.r, cur.cnt});
        // push the swapped continuations, reverse order to keep DFS order
        for (int i = cur.r; i > cur.l; --i) {
            string ns = cur.s;
            swap(ns[cur.l], ns[i]);
            st.push({ns, cur.l + 1, cur.r, cur.cnt + 1});
        }
    }
    return best;
}

