    st.push(std::move(s));
    while (!st.empty()) {
        std::string cur = std::move(st.top());
        st.pop();

        int start = -1;
        bool found = false;
        for (size_t i = 0; i < cur.size(); ++i) {
            if (cur[i] == '(') {
                start = static_cast<int>(i);
            } else if (cur[i] == ')') {
                if (start == -1) continue;
                std::string t = cur.substr(start + 1, i - start - 1);
                std::reverse(t.begin(), t.end());
                std::string next = cur.substr(0, start) + t + cur.substr(i + 1);
                st.push(std::move(next));
                found = true;
                break;
            }
        }
        if (!found) {
            return cur;
        }
    }
    return s;
}

