    std::stack<std::pair<int,bool>> st;
    st.push({index, false});
    while(!st.empty()){
        auto [i, visited] = st.top();
        st.pop();
        if(i < 0) continue;
        if(i == 0){
            ldp[i] = height[i];
            continue;
