NestedInteger deserializeHelper(const string& s, int *i) {
    int idx = *i;
    if (idx >= (int)s.size() || s[idx] != '[') {
        int j = idx;
        while (j < (int)s.size() && (s[j] == '-' || isdigit(s[j]))) ++j;
        NestedInteger result;
        result.setInteger(stoi(s.substr(idx, j - idx)));
        *i = j;
        return result;
    }

    std::vector<NestedInteger> nodes;
    nodes.emplace_back();
    std::stack<int> st;
    st.push(0);
    ++idx;

    while (idx < (int)s.size()) {
        char c = s[idx];
        if (c == '[') {
            nodes.emplace_back();
            st.push((int)nodes.size() - 1);
            ++idx;
        } else if (c == ']') {
            int finished = st.top(); st.pop();
            if (st.size() == 1) {
                *i = idx + 1;
                return nodes[finished];
            } else {
                int parent = st.top();
                nodes[parent].add(nodes[finished]);
            }
            ++idx;
        } else if (c == ',') {
            ++idx;
        } else if (c == '-' || isdigit(c)) {
            int j = idx;
            while (j < (int)s.size() && (s[j] == '-' || isdigit(s[j]))) ++j;
            NestedInteger num;
            num.setInteger(stoi(s.substr(idx, j - idx)));
            int parent = st.top();
            nodes[parent].add(num);
            idx = j;
        } else {
            ++idx;
        }
    }
    *i = idx;
    return NestedInteger();
}

