int LISS(node* root) {
    if (!root) return 0;
    // explicit stack replaces the call stack
    std::stack<pair<node*, bool>> st;
    st.emplace(root, false);
    unordered_map<node*, pair<int,int>> dp; // {incl, excl}
    while (!st.empty()) {
        auto [n, visited] = st.top();
        st.pop();
        if (!n) continue;
        if (visited) {
            int incl = 1;
            int excl = 0;
            if (n->left) {
                incl += dp[n->left].second; // children must be excluded
                excl += max(dp[n->left].first, dp[n->left].second);
            }
            if (n->right) {
                incl += dp[n->right].second;
                excl += max(dp[n->right].first, dp[n->right].second);
            }
            dp[n] = {incl, excl};
        } else {
            st.emplace(n, true);
            if (n->right) st.emplace(n->right, false);
            if (n->left)  st.emplace(n->left, false);
        }
    }
    auto &p = dp[root];
    return max(p.first, p.second);
}

