using namespace std;

int factorialUsingRecursion(int n) {
    if (n == 0) return 1;
    // Explicit stack replaces the implicit call stack
    std::stack<int> st;
    st.push(n);
    int result = 1;
    while (!st.empty()) {
        int cur = st.top();
        st.pop();
        if (cur <= 0) {
            continue; // base case
        }
        result *= cur;
        // push the argument that the recursive call would have been made with
        if (cur > 1) {
            st.push(cur - 1);
        }
    }
    return result;
}

