        char ch;
        size_t i = 0;
        int j = -1;
        string remStr;
        int stage = 0;
    };
    std::stack<Frame> st;
    st.push({s, ch, 0, -1, "", 0});
    string result;
    while (!st.empty()) {
        Frame &cur = st.top();
        if (cur.s.size() <= 1) {
            result = cur.s;
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                parent.remStr = result;
                parent.stage = 1;
            }
            continue;
        }
        if (cur.stage == 0) {
            if (cur.i >= cur.s.size()) {
                result = cur.s;
                st.pop();
                if (!st.empty()) {
                    Frame &parent = st.top();
                    parent.remStr = result;
                    parent.stage = 1;
                }
                continue;
            }
            if (cur.i + 1 < cur.s.size() && cur.s[cur.i] == cur.s[cur.i + 1]) {
                int j = (int)cur.i;
                while (j + 1 < (int)cur.s.size() && cur.s[j] == cur.s[j + 1]) ++j;
                cur.j = j;
                char lastChar = cur.i > 0 ? cur.s[cur.i - 1] : cur.ch;
                string suffix = cur.s.substr(j + 1);
                Frame child;
                child.s = std::move(suffix);
                child.ch = lastChar;
                st.push(std::move(child));
                cur.stage = 1;
                continue;
            } else {
                ++cur.i;
                continue;
            }
        } else {
            cur.s = cur.s.substr(0, cur.i);
            while (!cur.remStr.empty() && !cur.s.empty() && cur.remStr[0] == cur.s.back()) {
