int mypow(int a, int k){
    if (k == 0) return 1;
    struct Frame {
        int a;
        int k;
        int stage; // 0 = entry, 1 = child done
        int t;
    };
    std::stack<Frame> st;
    st.push({a, k, 0, 0});
    int result = 1;
    while (!st.empty()) {
        Frame &f = st.top();
        if (f.k == 0) {
            int val = 1;
            st.pop();
            if (!st.empty()) {
                Frame &parent = st.top();
                parent.t = val;
                parent.stage = 1;
            } else {
                result = val;
            }
            continue;
        }
        if (f.stage == 0) {
            f.stage = 1;
            st.push({f.a, f.k / 2, 0, 0});
            continue;
        }
        int res = f.t * f.t;
        if (f.k % 2) res *= f.a;
        st.pop();
        if (!st.empty()) {
            Frame &parent = st.top();
            parent.t = res;
            parent.stage = 1;
        } else {
            result = res;
        }
    }
    return result;
}

