int seriesSum(int calculated,int current,int N) {
    std::stack<std::pair<int,int>> st;
    st.push({calculated, current});
    long long sum = 0;
    while (!st.empty()) {
        int calc = st.top().first;
        int curLen = st.top().second;
        st.pop();
        if (curLen == N + 1) continue;
        long long prod = 1;
        for (int i = calc; i < calc + curLen; ++i) {
            prod *= i;
        }
        sum += prod;
        int nextCalc = calc + curLen;
        int nextCur = curLen + 1;
        st.push({nextCalc, nextCur});
    }
    return static_cast<int>(sum);
}

