void dfs(const vector<int>& bricks, int width, int cur, int state, vector<int>& rows){
    struct Frame { int cur; int state; };
    std::stack<Frame> st;
    st.push({cur, state});
    while(!st.empty()){
        Frame f = st.top();
        st.pop();
        int cur_ = f.cur;
        int state_ = f.state;
        if(cur_ == width){
            rows.push_back(state_ ^ (1 << width));
            continue;
        }
        for(int i = static_cast<int>(bricks.size()) - 1; i >= 0; --i){
            int brick = bricks[i];
            int next_cur = cur_ + brick;
            if(next_cur <= width){
                int next_state = state_ | (1 << next_cur);
                st.push({next_cur, next_state});
            }
        }
    }
}

