using namespace std;
int nthTerm(int N) {
    if (N <= 0) return 0; // guard, original would recurse forever
    stack<int> st;
    st.push(N);
    // Build an explicit call chain: push start, then push the argument that each recursive call would receive
    while (st.top() > 1) {
        int cur = st.top(); st.pop();
        st.push(cur);      // keep current frame
        st.push(cur - 1);  // argument for nthTerm(N-1)
    }
    // Unwind the explicit stack in reverse order, reproducing the recursive returns
    int result = 2; // base case nthTerm(1)
    st.pop(); // remove the 1
    while (!st.empty()) {
        int cur = st.top(); st.pop();
        result = (cur - 1) * 13 + result;
    }
    return result;
}
